// Codility logo data URIs — auto-generated from codility-wordmark-*.svg
// Used by the PPTX export (PptxGenJS needs data URIs to embed images;
// fetch() of sibling files is blocked on file://). Banding-element URIs
// come in two tones: the native pale shape for dark/saturated surfaces
// (rendered at ~8% white opacity), and a slightly darker variant for
// paper surfaces so it remains visible against the near-white bg.
window.CODILITY_LOGO_DARK_URI    = "data:image/png;base64,";
window.CODILITY_LOGO_LIGHT_URI   = "data:image/png;base64,";
window.CODILITY_BANDING_URI      = "data:image/svg+xml;base64,";
window.CODILITY_BANDING_PAPER_URI= "data:image/svg+xml;base64,";
